"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[2564],{3232(a){a.exports=JSON.parse('{"title":"\uc6f9\uacfc \ub2e4\ub978 \uae30\uc220\uc758 \uc735\ud569","date":"2024-01-18","coverUrl":null,"html":"<h2 data-notion-block-id=\\"59b92163-82ad-475b-9b80-f9c8f5ce6309\\" id=\\"59b92163-82ad-475b-9b80-f9c8f5ce6309\\">Sentry\uc5d0\uc11c \ubaa8\ub4e0 \uad11\uace0 \ucfe0\ud0a4 \uc81c\uac70 \uc0ac\ub840</h2><a href=\\"https://blog.sentry.io/we-removed-advertising-cookies-heres-what-happened/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.sentry.io/we-removed-advertising-cookies-heres-what-happened/</a><p data-notion-block-id=\\"cd85298a-ca6a-4568-a4ec-38e097ee74c1\\"><b>\uc2ec\uc724\uc12d</b>: \ucd5c\uc2e0 \uc6f9\uc0ac\uc774\ud2b8\uc5d0\uc11c GA4\uc5c6\uc774 \uc0ac\uc6a9\uc790\uc758 flow\ub97c \uce21\uc815\ud558\uae30\ub294 \uc27d\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc Sentry\ub294 \ud06c\ub86c\uc758 \uc368\ub4dc \ud30c\ud2f0 \ucfe0\ud0a4 \ucc28\ub2e8\uc744 \ubcf4\uace0 \ubbf8\ub798 \ubaa8\ub378(\ucfe0\ud0a4\ub9ac\uc2a4 \ucd94\uc801)\uae4c\uc9c0 \uba3c\uc800 \uc801\uc6a9\ud558\ub294 \uc77c\uc744 \uc218\ud589\ud588\uace0, \uc774\ub97c \uc5b4\ub5bb\uac8c \ud588\ub294\uc9c0 \uacfc\uc815\uacfc \uacb0\uacfc\ub97c \uc18c\uac1c\ud569\ub2c8\ub2e4. \uc6b0\ub9ac\ub098\ub77c\ub294 \uad11\uace0\ucc28\ub2e8\uae30 \uc0ac\uc6a9\ub960\uc774 \ub192\uc9c0 \uc54a\uc744\uac83\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uc9c0\ub9cc, \ubbf8\uad6d\uc758 \ube44\uc728\ub85c \ubcf4\uba74 \uaf64\ub098 \ub192\uc740 \uac83\uc744 \uc0dd\uac01\ud558\uba74 \ud574\uc57c\ub9cc \ud55c\ub2e4\uace0 \uc0dd\uac01\ud558\uae30\ub3c4 \ud569\ub2c8\ub2e4(\uc6b0\ub9ac\ub098\ub77c\uc5d0\uc11c \uba3c\uc800 \ucfe0\ud0a4\ub9ac\uc2a4 \ucd94\uc801\uc744 \uc801\uc6a9\ud558\uac70\ub098 GDPR, CCPA\uac19\uc740 \uaddc\uc815\uc744 \ub3c4\uc785\ud558\uae30\uc5d4 \uba40\uc5c8\uad6c\uc694).</p><p data-notion-block-id=\\"94666487-6c87-4a78-b666-7b9eb045a9a9\\"><b>\uae40\ub300\uad00</b>: \ud68c\uc0ac\uc5d0\uc11c GA4\ub97c \ud1b5\ud574 flow\ub97c \ucd94\uc801\ud558\ub294 \uae30\ub2a5\uc744 \uc2e4\uc81c\ub85c \ub3c4\uc785\ud558\uace0 \uc774\ub97c \ud1b5\ud574 \ud68c\uc0ac\ub97c \uc131\uc7a5\ud558\ub294\ub370 \ub9e4\uc6b0 \uc911\uc694\ud55c \ud3ec\uc778\ud2b8\ub77c\ub294 \uac83\uc740 \ubab8\uc73c\ub85c \uc54c\uace0 \uc788\uc5c8\uc9c0\ub9cc, \ud574\uc678\uc5d0\uc11c\ub294 \uc774\ub7ec\ud55c \ub370\uc774\ud130 \uc218\uc9d1\uc5d0 \ub300\ud55c \ucfe0\ud0a4 \ubb38\uc81c\uc5d0 \ub300\ud574 \uc0c8\ub86d\uac8c \uc54c\uac8c \ub418\uc5c8\ub124\uc694.</p><h2 data-notion-block-id=\\"a4c4f929-95ac-4eb6-ba62-b6bd581b3b62\\" id=\\"a4c4f929-95ac-4eb6-ba62-b6bd581b3b62\\"> \uc6f9\uacfc \ub2e4\ub978 \uae30\uc220\uc758 \uc735\ud569</h2><a href=\\"https://jakelazaroff.com/words/the-website-vs-web-app-dichotomy-doesnt-exist/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://jakelazaroff.com/words/the-website-vs-web-app-dichotomy-doesnt-exist/</a><p data-notion-block-id=\\"4c334aa1-3f49-4157-9038-32084285c2fe\\"><b>\uc2ec\uc724\uc12d</b>: \ucd5c\uc2e0 \uc6f9 \uae30\uc220\uc744 \ud604 \uc2dc\uc810\uc758 \uc6f9 \uc911\uc2ec \uc11c\ube44\uc2a4\ub4e4\uc740 \uc5b4\ub5bb\uac8c \uc735\ud569\uc744 \ud588\ub294\uc9c0 \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. \ucd5c\uc2e0 \uc6f9 \uae30\uc220\uacfc \ud568\uaed8 \uc774\ub7f0 \uc11c\ube44\uc2a4\uac00 \uc788\ub2e4\ub97c \ubcf4\uba74 \uc88b\uc744 \uac83 \uac19\uc544 \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4. \ud2b9\ud788 \uc6f9 \uae30\uc220\uacfc \uc624\ud504\ub77c\uc778 \uc6b0\uc120 \uc18c\ud504\ud2b8\uc6e8\uc5b4\ub97c \ud569\uce5c \uc11c\ube44\uc2a4\ub97c \uac15\uc870\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4(Notion\uc774 \ub4f1\uc7a5\ud558\uba74\uc11c \uac00\uc18d\ud654\ub41c \uac70 \uac19\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4).</p><p data-notion-block-id=\\"c5251c98-feb3-44d3-a9ca-1ebecbcdd8c0\\"><b>\ucd5c\uc6d0\ube48</b>: \ucd5c\uc2e0 \uc2a4\ud399\uc758 \uc6f9\uc740 \ub3d9\uc801\uc778 HTML \uc694\uc18c\ub4e4\uacfc, CSS\uc758 \ucd94\uac00\ub85c \uc810\uc810 JS \ud504\ub808\uc784\uc6cc\ud06c\uc5d0 \ub300\ud55c \uc758\uc874\uc744 \uc904\uc5ec\uac00\uac8c\ub054 \ubc1c\uc804\ud558\ub294 \uac83\uc73c\ub85c \ubcf4\uc774\ub294\ub370, \uadf8\uc640\uc911\uc5d0 HTMX\ub3c4 \uc810\ucc28 \uc0c8\ub85c\uc6b4 \ubc29\ud5a5\uc131\uc744 \uc81c\uc2dc\ud558\uace0 \uc788\uc8e0. \uc624\ud504\ub77c\uc778 \uc6b0\uc120, \ub85c\uceec \uc6b0\uc120\uc778 \ud504\ub85c\uc81d\ud2b8\ub4e4\uc744 \uad6c\ubd84\ud55c \uac83\uc774 \uc778\uc0c1\uc801\uc778\ub370, \uc774\ub807\uac8c \uad6c\ubd84\ud574\ubcf4\ub2c8 \ub3d9\uc801\uc774\uc9c0 \uc54a\uc740 \ud504\ub85c\uc81d\ud2b8\uc5d0\uc11c\ub294 \uc815\ub9d0\ub85c \ud504\ub808\uc784\uc6cc\ud06c\ub97c \ub5bc\ub294 \ubbf8\ub798\uac00 \uc624\uaca0\ub2e4 \uc2f6\ub124\uc694.</p><p data-notion-block-id=\\"cb128187-f387-49b6-8a35-cbfdb01fdaa1\\"><b>\uae40\ub300\uad00</b>: \uc6f9\uc571\uacfc \uc6f9\uc0ac\uc774\ud2b8\uc758 \uacbd\uacc4\uc5d0 \ub300\ud574\uc11c \uc0dd\uac01\uce58 \ubabb\ud588\ub358 \ubd80\ubd84\ub4e4\uc5d0 \ub300\ud574\uc11c \uac01 \uc694\uc18c\ubcc4 \uad6c\ubd84\ubc95\uc774 \ud55c\ub208\uc5d0 \ub4e4\uc5b4\uc654\uc2b5\ub2c8\ub2e4. \uc774\ub7ec\ud55c \uc6f9\uc571\uacfc \uc6f9\uc0ac\uc774\ud2b8\uc758 \uacbd\uacc4\uac00 \uac10\uc18c\ud558\uba74\uc11c \uc6f9\uc740 \uc880 \ub354 \uc804\ubb38\uc801\uc778 \uae30\uc220\uc744 \uc694\ud560 \uc218 \uc788\uc74c\uc744 \ub290\ub07c\uac8c \ub418\uc5c8\uace0 FrontEnd\uc5d0 \ub300\ud55c \uc55e\uc73c\ub85c\uc758 \ubc1c\uc804\ub3c4 \uae30\ub300\uac00 \ub429\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"12c2ec72-b604-413e-89e5-a73e42245485\\" id=\\"12c2ec72-b604-413e-89e5-a73e42245485\\">CSS \ucd5c\uc2e0 \ub3c4\uad6c\ub4e4</h2><a href=\\"https://leerob.io/blog/css\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://leerob.io/blog/css</a><p data-notion-block-id=\\"729da09f-5985-4cfd-896d-b0a70802fdb1\\"><b>\uc2ec\uc724\uc12d</b>: CSS \ucd5c\uc801\ud654\ub97c \uc704\ud55c \uc5ec\ub7ec \ub3c4\uad6c\ub4e4(zero runtime CSS-in-JS, LightningCSS\u2026)\uacfc \ube0c\ub77c\uc6b0\uc800\uc5d0 \uacf5\ud1b5\uc73c\ub85c \ucd94\uac00\ub418\ub294 CSS\ub4e4(Interop 2023)\uc740 CSS\uc5d0 \ub300\ud55c \uad00\uc2ec\uc744 \uadf8\ub300\ub85c \ubc18\uc601\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uadf8\uac83\ub4e4 \uc911 \uc5b4\ub5a4 \uac83\uc774 (\uc790\uc2e0\uc774) \uc8fc\ubaa9\ud558\uace0 \uc788\ub294\uc9c0\ub97c \uc774 \uae00\uc5d0 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4. \ucd5c\uadfc CSS\ub3c4 \ube60\ub978 \uc18d\ub3c4\ub85c \uae30\uc220\uc774 \ub098\uc624\ub294 \uac8c \ub9ce\uc544\uc11c \ubcf4\uc2dc\uae30\ub97c \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4. \ucd94\uac00\ub418\ub294 CSS\uc5d0 \ub300\ud55c \uc815\ubcf4\ub294 <a href=\\"https://web.dev/blog/interop-2023?hl=ko\\">Interop 2023</a>\uc744 \ubcf4\uba74 \ub3c4\uc6c0\uc774 \ub420 \uac81\ub2c8\ub2e4.</p><p data-notion-block-id=\\"b29ac433-7307-4ff5-af6a-60a247f1ef5c\\"><b>\ucd5c\uc6d0\ube48</b>: \uc911\ucca9 CSS\uc640 <code>@container</code> \ucffc\ub9ac\uac00 \ud575\uc2ec \ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c \uc804\ubd80 \uc9c0\uc6d0\ub418\uac8c\ub054 \ucd94\uac00\ub418\uc5c8\ub124\uc694! <a href=\\"https://io.google/2023/program/cafbe05a-c19e-4fe5-9e25-61c5c0c2f6cf/intl/ko/\\">2023 Google I/O\uc758 \uc18c\uac1c\uc601\uc0c1</a>\uc5d0\uc11c\ub3c4 \ud765\ubbf8\ub86d\uac8c \ubd24\uc5c8\ub294\ub370, \uac00\ub2a5\ud55c \ube68\ub9ac \uc775\uc219\ud574\uc838\ubcfc \uc608\uc815\uc774\uc608\uc694.</p><p data-notion-block-id=\\"53c22e33-8f17-43a2-8f03-73a536e399f7\\"><b>\uae40\ub300\uad00</b>: CSS\uac00 2024\ub144\ub3c4 \uc8fc\ubaa9\ud560 \uae30\uc220\uc778 nesting, :has, subgrid, container query\uc5d0 \ub300\ud574\uc11c\ub294 \ud655\uc2e4\ud788 \uc54c\uace0\uac00\uc2dc\uae38 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4!! \uc0c1\ub2f9\ud788 \uac15\ub825\ud55c \uae30\uc220\ub85c \ud3c9\uac00\ub418\uace0 \uc788\uc5b4 \ub2e4\ub978 css \uc5b8\uc5b4\uc5d0 \ub300\ud55c \ubc18\uc601\ub3c4 \uae30\ub300\uac00 \ub429\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"92ba5ea7-34af-414d-ba66-113930177acf\\" id=\\"92ba5ea7-34af-414d-ba66-113930177acf\\">Rust \uae30\ubc18 \ub9b0\ud2b8 \ud234\uc758 \uae30\ub2a5 \ubd80\uc871</h2><a href=\\"https://www.joshuakgoldberg.com/blog/rust-based-javascript-linters-fast-but-no-typed-linting-right-now/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.joshuakgoldberg.com/blog/rust-based-javascript-linters-fast-but-no-typed-linting-right-now/</a><p data-notion-block-id=\\"091e1010-4b8d-4753-9ec6-b5c2da7596ca\\"><b>\uc2ec\uc724\uc12d</b>: Rust\uae30\ubc18\uc73c\ub85c \ub41c \ud234\uc774 \ub098\uc654\uc74c\uc5d0\ub3c4 \ubd88\uad6c\ud558\uace0, \uc791\ub3d9\ud558\uc9c0 \uc54a\ub294 \uc5d0\uc9c0 \ucf00\uc774\uc2a4\ub4e4\uc774 \ub9ce\uc774 \uc788\uc73c\ubbc0\ub85c \uc7a5\ub2e8\uc810\uc744 \uc0b4\ud3b4\ubd10\uc57c \ud55c\ub2e4\ub294 \uae00\uc785\ub2c8\ub2e4. \uc544\uc27d\uac8c\ub3c4 \ub9b0\ud2b8 \ud234\uc744 \ubc14\uafc0 \ub54c\ub294 \uc544\uc9c1 \uba40\uc5c8\ub2e4\uace0 \ubcfc \uc218 \uc788\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"9a381a1f-cb0f-4ddc-9618-f562bc5ac748\\" id=\\"9a381a1f-cb0f-4ddc-9618-f562bc5ac748\\">React \uc0ac\uc6a9\uc790\uc758 \ub450\uac00\uc9c0 \uc811\uadfc</h2><a href=\\"https://overreacted.io/the-two-reacts/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://overreacted.io/the-two-reacts/</a><p data-notion-block-id=\\"88e73587-f0d8-4553-b58e-5a2aa4eb0803\\"><b>\uc2ec\uc724\uc12d</b>: \uc11c\ubc84\uce21 \ub80c\ub354\ub9c1\uacfc \ud074\ub77c\uc774\uc5b8\ud2b8\uce21 \ub80c\ub354\ub9c1\uc774 \ub9ac\uc561\ud2b8\uc5d0\uc11c \uc5b4\ub5bb\uac8c \uad6c\ud604\ub418\uc5b4\uc654\ub294\uc9c0\ub97c \uc124\uba85\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uae00\uc4f4\uc774\uac00 \uc5b4\ub5bb\uac8c \ud574\uc57c \ud558\ub098\uc694?\ub85c \ub05d\ub0c8\uace0, \uc774 \uc774\ud6c4\uc758 \uae00\ub3c4 \uc4f4\ub2e4\ub294 \uac83\uc744 \ubcf4\ub2c8, RSC\uac00 \uc774\ub97c \uc5b4\ub5bb\uac8c \ud574\uacb0\ud588\ub294\uc9c0\ub97c \uc4f0\ub824\uace0 \ud558\ub294 \uac83 \uac19\uc2b5\ub2c8\ub2e4. \ubb3c\ub860 RSC\uac00 \ud574\uacb0 \ubc29\ubc95\uc774 \ub420 \uc218\ub3c4 \uc788\uaca0\uc9c0\ub9cc \uc804 \ub274\uc2a4\ub808\ud130\uc5d0\uc11c \ubd24\ub4ef\uc774 \ub9ce\uc740 \uc0ac\ub78c\ub4e4\uc740 \uc544\ub2c8\ub77c\uace0 \ub9d0\ud558\ub294 \uac83 \uac19\uc2b5\ub2c8\ub2e4.</p><p data-notion-block-id=\\"85f6731d-33e8-4ca6-b261-0f3a93e2db7c\\"><b>\uae40\ub300\uad00</b>: \uc815\ub9d0 \ub2e8\uc21c\ud55c \uc811\uadfc\uacfc \uc608\uc2dc\ub97c \ud1b5\ud574 \uc11c\ubc84\uce21 \ub80c\ub354\ub9c1\uacfc \ud074\ub77c\uc774\uc5b8\ud2b8 \ub80c\ub354\ub9c1\uc758 \uad6c\ud604\uc774 \uc6a9\uc774\ud55c\uc9c0\ub97c \uc124\uba85\ud558\ub294 \ubd80\ubd84\uc774 \uc778\uc0c1\uc801\uc774\uc5c8\uc2b5\ub2c8\ub2e4. \uc774\uc640 \uc720\uc0ac\ud558\uac8c \ub9ac\uc561\ud2b8\ub9cc \uc0ac\uc6a9\ud558\ub2e4\uac00 NextJS\uac00 \ud544\uc694\ud55c \uc21c\uac04\uc744 \ub290\ub07c\uc2e0\ub2e4\uba74, <a href=\\"https://ninetailed.io/blog/next-js-vs-react/\\">\ud2b9\uc9d5\uc5d0 \ub300\ud55c \ube44\uad50</a>\ub97c \ucc38\uace0\ud558\uc2dc\uba74 \uc88b\uc744 \uac83 \uac19\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"044001fa-1dbc-4917-b44c-2bdd76152522\\" id=\\"044001fa-1dbc-4917-b44c-2bdd76152522\\">ContextAPI\uc758 \ub354 \ub098\uc740 \ub300\uc548</h2><a href=\\"https://interbolt.org/blog/react-use-selector-optimization/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://interbolt.org/blog/react-use-selector-optimization/</a><p data-notion-block-id=\\"8740d898-73a5-4faa-ae32-ed874d886cb9\\"><b>\uc2ec\uc724\uc12d</b>: Context API\ub294 \ub9ce\uc740 \uc0ac\ub78c\uc774 \uc4f0\uace0 \uc788\uc74c\uc5d0\ub3c4 \ubd88\uad6c\ud558\uace0 \uc7ac\ub80c\ub354\ub9c1 \uc131\ub2a5 \uc774\uc288\uac00 \uc874\uc7ac\ud569\ub2c8\ub2e4. <a href=\\"https://github.com/dai-shi/use-context-selector\\">\uad00\ub828 \ub300\uccb4 \ub77c\uc774\ube0c\ub7ec\ub9ac</a>\ub3c4 \uc788\uc74c\uc774 \uc774\ub97c \ub300\ubcc0\ud569\ub2c8\ub2e4. React\uc758 \uc2e0 \uae30\ub2a5\uc740 \uc774\ub97c \ub300\uccb4\ud560 \uc218 \uc788\ub2e4\ub294 \uc2dd\uc758 \uae00\uc785\ub2c8\ub2e4. Context API\ub294 \ub9ce\uc740 \uc0ac\ub78c\ub4e4\uc774 \uc54c\uc9c0\ub9cc, \uc7ac\ub80c\ub354\ub9c1 \uc774\uc288\ub294 \ub9ce\uc740 \uc0ac\ub78c\ub4e4\uc774 \uc54c\uace0 \uc788\uc9c0 \uc54a\uc544\uc11c \ub9ce\uc740 \uc0ac\ub78c\ub4e4\uc774 \uc54c\uc558\uc73c\uba74 \uc88b\uaca0\uc2b5\ub2c8\ub2e4.</p><p data-notion-block-id=\\"75341257-cadc-4db1-bb24-176398a4cfa5\\"><b>\ucd5c\uc6d0\ube48</b>: React \uacf5\uc2dd \ubb38\uc11c\uc5d0 \uc7ac\ub80c\ub354\ub9c1 \uc774\uc288\uac00 \ud574\uacb0\ub41c \uc644\uc804\ud55c best practice\uac00 \uc791\uc131\ub418\uae30 \uc804\uae4c\uc9c0\ub294 \uc7ac\ub80c\ub354\ub9c1 \uc774\uc288\uac00 \uc5c6\ub294 \uac00\ubccd\uace0 \uc548\uc815\uc801\uc778 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub4e4\uc744 \uacc4\uc18d \uc368\uc57c\uaca0\ub124\uc694. \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc644\uc804\ud788 \ubc97\uc5b4\ub098 \uc6a9\ub7c9\uc744 \uc904\uc77c \uc218 \uc788\uac8c \ub41c\ub2e4\uba74 \ubca0\uc2a4\ud2b8\uaca0\uc9c0\ub9cc\uc694.</p><h2 data-notion-block-id=\\"d975772d-52ea-4d7f-8de7-d6d1317769f8\\" id=\\"d975772d-52ea-4d7f-8de7-d6d1317769f8\\">React\uc5d0\uc11c Web Vitals \uce21\uc815 \ubc29\ubc95</h2><a href=\\"https://www.debugbear.com/blog/soft-navigations-react-tutorial\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.debugbear.com/blog/soft-navigations-react-tutorial</a><p data-notion-block-id=\\"b207e5bb-9095-415b-89e7-036923f78dae\\"><b>\uc2ec\uc724\uc12d</b>: \uac1c\ubc1c \uc911\uc5d0 Web Vitals\ub97c \ubcfc \uc218 \uc788\ub294 \ubc29\ubc95\uc744 \uc18c\uac1c\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc608\uc2dc\ub97c React\ub85c \ub4e4\uc5c8\uc9c0\ub9cc \ub2e4\ub978 \ud504\ub808\uc784\uc6cc\ud06c\uc5d0\ub3c4 \uc801\uc6a9\ud560 \uc218 \uc788\uc73c\ub2c8 Web Vital \uce21\uc815\ubc29\ubc95 \uc911\uc5d0 \ud558\ub098\ub85c \uc54c\uace0 \uc788\uc73c\uba74 \ub3c4\uc6c0\uc774 \ub420 \uac83 \uac19\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"975b9311-0b83-42a2-9d9b-9d232c29f638\\" id=\\"975b9311-0b83-42a2-9d9b-9d232c29f638\\">Vue 3.4 \ubc30\ud3ec</h2><a href=\\"https://blog.vuejs.org/posts/vue-3-4\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.vuejs.org/posts/vue-3-4</a><p data-notion-block-id=\\"3661d37d-2581-40a1-b67b-ec58cbd9b662\\"><b>\uc2ec\uc724\uc12d</b>: Vue 3\uac00 \uc5c5\ub370\uc774\ud2b8\ub97c \ud560 \ub54c \uc2e0 \uae30\ub2a5\ubcf4\ub2e4 \uac1c\ubc1c\uc790 \uacbd\ud5d8\uc5d0 \ud22c\uc790\ud558\uace0 \uc788\ub2e4\ub294 \uc810\uc5d0\uc11c React\uc640 \ub300\ube44\ub418\uc5b4 \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"e09fbed1-f7ba-4a29-b670-619ce30d78ea\\" id=\\"e09fbed1-f7ba-4a29-b670-619ce30d78ea\\">\ud604\uc7ac PWA\ub294 \ubb34\uc5c7\uc744 \ud560 \uc218 \uc788\ub294\uac00?</h2><a href=\\"https://whatpwacando.today/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://whatpwacando.today/</a><p data-notion-block-id=\\"f704bde3-d222-4da8-b03f-ec6e809756a6\\">\ub531\ud788 \uae00\uc740 \uc544\ub2c8\uace0, PWA\uc5d0 \uad00\uc2ec\uc788\ub294 \uc0ac\ub78c\uc774 \uc5b4\ub5a4 \uae30\ub2a5\uc744 \uc5b4\ub5a4 UX\ub97c \ud1b5\ud574 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294\uac00\ub97c \ubcf4\uc5ec\uc8fc\ub294 \uc6f9\uc0ac\uc774\ud2b8\uc785\ub2c8\ub2e4.</p>"}')}}]);